def predict(board, action):
    mouse_row, mouse_col = action[1], action[2]
    mouse_char = board[mouse_row][mouse_col]

    if mouse_char == 'W':
        board[mouse_row][mouse_col] = 'p'
    else:
        for i in range(max(0, mouse_col-1), min(64, mouse_col+2)):
            if board[mouse_row][i] == 'B':
                board[mouse_row][i] = mouse_char
            elif board[mouse_row][i] == 'G':
                board[mouse_row][i] = 'S'
            elif board[mouse_row][i] == 'N':
                board[mouse_row][i] = 'S'

    return [''.join(row) for row in board]
